\begin{tikzpicture}
\begin{axis}[
    width=\textwidth,
    height=0.72\textwidth,
    xmin=0, xmax=3.25,
    ymin=-45, ymax=60,
    axis lines=middle,
    xlabel={\(t\) (hours)},
    ylabel={\(v(t)\)},
    xtick={0,1,2,3},
    ytick={-30,0,40},
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
]
\draw[fill=gray!15, fill opacity=0.6, draw=none] (axis cs:0,0) rectangle (axis cs:2,40);
