\addplot[thick] coordinates {(0,40) (2,40)};
\addplot[thick] coordinates {(2,-30) (3,-30)};
\draw[dashed] (axis cs:2,-35) -- (axis cs:2,45);
\node[anchor=south] at (axis cs:1,40) {\(+80\)};
\node[anchor=north] at (axis cs:2.5,-30) {\(-30\)};
\end{axis}
\end{tikzpicture}

